package career.assistant.cleanup; import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID; @Entity @Table(name="cleanup_audit_entries") public class CleanupAuditEntry{@Id @GeneratedValue private UUID id;@Column(name="run_at",nullable=false)private OffsetDateTime runAt;@Column(name="dry_run",nullable=false)private boolean dryRun;@Column(nullable=false)private String category;@Column(name="entity_id")private UUID entityId;@Column(name="storage_path")private String storagePath;@Column(nullable=false)private String action;@Column(columnDefinition="TEXT")private String details;@PrePersist void create(){if(runAt==null)runAt=OffsetDateTime.now();}public void setDryRun(boolean v){dryRun=v;}public void setCategory(String v){category=v;}public void setEntityId(UUID v){entityId=v;}public void setStoragePath(String v){storagePath=v;}public void setAction(String v){action=v;}public void setDetails(String v){details=v;}}
